// Direct official sources only: restaurant/brand promo pages, museum free-day pages, birthday-reward program pages,
// public giveaway rules pages, partner-supplied promos. One item per source. Edit this list; never add aggregator rumors.
return [
  // { json: { city_key: 'atlanta', merchant_name: 'Example', category: 'food_drinks', offer_type: 'free', source_url: 'https://example.com/promo', title_hint: '' } },
].map(x => x);

// Keep only offers whose OFFICIAL page is live (2xx), names the merchant, mentions the city or a participating
// location, and states an end date we can parse (or is an evergreen birthday program). Everything else is dropped.
const out = [];
for (const item of $input.all()) {
  const src = $('Source list (official only)').item.json;
  const status = item.json.statusCode || 0; const body = String(item.json.body || item.json.data || '').toLowerCase();
  if (status < 200 || status > 299) continue;
  if (!body.includes(String(src.merchant_name || '').toLowerCase())) continue;
  if (!/atlanta|\bga\b|georgia/.test(body) && src.category !== 'birthday') continue;
  const m = body.match(/(?:ends?|expires?|valid (?:through|until)|through)\s+([a-z]{3,9}\.? \d{1,2}(?:, ?\d{4})?)/);
  const expires = m ? new Date(m[1]) : null;
  if (src.category !== 'birthday' && !(expires && !isNaN(expires) && expires > new Date())) continue;
  out.push({ json: { ...src, expires_at: expires && !isNaN(expires) ? expires.toISOString() : null, dedupe: `${src.merchant_name}|${src.title_hint || src.source_url}`.toLowerCase() } });
}
return out;
